import sys
from typing import List
import json

class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        total_area = 0
        events = {}

        for x, y, l in squares:
            area = l * l
            total_area += area
            # Start event: slope increases by l at y
            if y not in events:
                events[y] = 0
            events[y] += l
            # End event: slope decreases by l at y + l
            end_y = y + l
            if end_y not in events:
                events[end_y] = 0
            events[end_y] -= l

        target = total_area / 2.0

        sorted_coords = sorted(events.keys())

        current_area = 0.0
        current_slope = 0
        prev_y = sorted_coords[0]

        # Iterate through intervals defined by sorted coordinates
        for y in sorted_coords:
            if y > prev_y:
                # Check if target is already reached at prev_y
                if current_area >= target:
                    return float(prev_y)

                dist = y - prev_y
                area_in_interval = dist * current_slope

                if current_area + area_in_interval >= target:
                    # Target is within this interval
                    if current_slope == 0:
                        # Should be covered by current_area >= target check, but for safety
                        return float(prev_y)
                    return prev_y + (target - current_area) / current_slope

                current_area += area_in_interval

            # Update slope for the next interval
            current_slope += events[y]
            prev_y = y

        return float(prev_y)

if __name__ == "__main__":
    input_str = sys.stdin.read().strip()
    if input_str:
        squares = json.loads(input_str)
        sol = Solution()
        result = sol.separateSquares(squares)
        print(f"{result:.5f}")
